/**
 * TLS-inspector domain benchmark (offline parse/registry subset).
 *
 * External vectors (all official, no homemade ground truth):
 *  - IANA TLS Cipher Suite Registry: official numeric IDs (0x1301 TLS_AES_128_GCM_SHA256,
 *    0x1302 TLS_AES_256_GCM_SHA384, 0x1303 TLS_CHACHA20_POLY1305_SHA256, 0xC02F
 *    ECDHE-RSA-AES128-GCM-SHA256, 0x002F AES_RSA_WITH_AES_128_CBC_SHA …)
 *  - NSS SSLKEYLOGFILE format (Mozilla/NSS): "CLIENT_RANDOM <64hex> <secret hex>" lines
 *  - X.509: a REAL self-signed certificate generated by node:crypto (OpenSSL), wrapped in
 *    the TLS Certificate message wire layout (RFC 8446 §4.4.2), parsed back
 */
import { TlsInspectorTlsHandlers } from '@server/domains/tls-inspector/handlers/tls-handlers';
import { body, type BenchSuite } from '../harness';
import { mkdtempSync, writeFileSync, readFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createHash } from 'node:crypto';

const handlers = new TlsInspectorTlsHandlers();

const tmp = mkdtempSync(join(tmpdir(), 'jshook-bench-tls-'));
process.once('exit', () => {
  try {
    require('node:fs').rmSync(tmp, { recursive: true, force: true });
  } catch {
    /* tmpdir */
  }
});

// REAL self-signed X.509 minted by the system OpenSSL binary (no homemade DER)
import { execFileSync } from 'node:child_process';
const keyPath = join(tmp, 'bench-key.pem');
const certPemPath = join(tmp, 'bench-cert.pem');
execFileSync(
  'openssl',
  [
    'req',
    '-x509',
    '-newkey',
    'rsa:2048',
    '-keyout',
    keyPath,
    '-out',
    certPemPath,
    '-days',
    '1',
    '-nodes',
    '-subj',
    '/CN=bench.jshook.local',
    '-sha256',
  ],
  { stdio: 'ignore' },
);
const certDer = (() => {
  const pem = readFileSync(certPemPath, 'utf8');
  const b64 = pem
    .replace(/-----BEGIN CERTIFICATE-----/, '')
    .replace(/-----END CERTIFICATE-----/, '')
    .replace(/\s+/g, '');
  return Buffer.from(b64, 'base64');
})();
const CERT_FINGERPRINT = createHash('sha256').update(certDer).digest('hex');

// TLS Certificate message wrapper (RFC 8446 §4.4.2): 3B total len, 3B cert len, cert
function wrapCertMessage(der: Buffer): string {
  const entry = Buffer.concat([Buffer.from([0, der.length >> 8, der.length & 0xff]), der]);
  const message = Buffer.concat([Buffer.from([0, entry.length >> 8, entry.length & 0xff]), entry]);
  return message.toString('hex');
}

// Minimal RFC 8446 ClientHello handshake record
function buildClientHelloHex(): string {
  const u16 = (n: number) => Buffer.from([(n >> 8) & 0xff, n & 0xff]);
  const u24 = (n: number) => Buffer.from([(n >> 16) & 0xff, (n >> 8) & 0xff, n & 0xff]);
  const ext = (type: number, data: Buffer) => Buffer.concat([u16(type), u16(data.length), data]);
  const host = Buffer.from('benchmark.example.com');
  const serverNameEntry = Buffer.concat([Buffer.from([0x00]), u16(host.length), host]);
  const serverName = ext(0x0000, Buffer.concat([u16(serverNameEntry.length), serverNameEntry]));
  const ciphers = Buffer.from([0x13, 0x01, 0x13, 0x02]);
  const hello = Buffer.concat([
    Buffer.from([0x03, 0x03]),
    Buffer.alloc(32, 0x42),
    Buffer.from([0x00]), // session_id
    u16(ciphers.length),
    ciphers,
    Buffer.from([0x01, 0x00]), // compression: null
    u16(serverName.length),
    serverName,
  ]);
  return Buffer.concat([
    Buffer.from([0x16, 0x03, 0x01]), // Handshake, TLS 1.0 record layer
    u16(hello.length + 4),
    Buffer.from([0x01]), // ClientHello
    u24(hello.length),
    hello,
  ]).toString('hex');
}

// NSS SSLKEYLOGFILE sample (official format from Mozilla NSS)
const CLIENT_RANDOM = 'a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8f90';
const SECRET_HEX = '11'.repeat(48); // TLS 1.3 secrets are 48 bytes
const keylogPath = join(tmp, 'sslkeylog.log');
writeFileSync(keylogPath, `CLIENT_RANDOM ${CLIENT_RANDOM} ${SECRET_HEX}\n`);

export const tlsSuite: BenchSuite = {
  name: 'tls-inspector',
  domain: 'tls-inspector',
  description:
    'IANA cipher registry parity, NSS keylog parsing, SPKI/certificate wire parsing (official formats)',
  cases: [
    {
      name: 'tls_cipher_suites/iana-registry-parity',
      tool: 'tls_cipher_suites',
      origin: 'external-vector',
      reference:
        'IANA TLS Cipher Suite Registry: official ids 0x1301/0x1302/0x1303/0xC02F/0x002F with correct AEAD and protocol metadata',
      run: () => handlers.handleCipherSuites({}),
      validate: (v) => {
        const b = body(v);
        const suites = (b.suites ?? b.cipherSuites ?? b.items ?? []) as Array<
          Record<string, unknown>
        >;
        if (!Array.isArray(suites) || suites.length === 0)
          return `no suite list: ${JSON.stringify(b).slice(0, 200)}`;
        const text = JSON.stringify(suites);
        const problems: string[] = [];
        // official IANA ids and names
        if (!text.includes('1301') || !text.includes('TLS_AES_128_GCM_SHA256'))
          problems.push('0x1301 TLS_AES_128_GCM_SHA256 missing');
        if (!text.includes('1303') || !text.toLowerCase().includes('chacha20'))
          problems.push('0x1303 TLS_CHACHA20_POLY1305 missing');
        if (!text.includes('c02f') && !text.includes('C02F') && !text.includes('49199'))
          problems.push('0xC02F ECDHE-RSA-AES128-GCM-SHA256 missing');
        if (problems.length > 0) return problems.join('; ');
        // AEAD flag on TLS 1.3 suites (normative: all TLS13 suites are AEAD)
        const aes128 = suites.find((s) => JSON.stringify(s).includes('TLS_AES_128_GCM_SHA256'));
        if (aes128 && JSON.stringify(aes128).toLowerCase().includes('aead') === false)
          return 'TLS_AES_128_GCM_SHA256 not flagged AEAD';
        return true;
      },
    },
    {
      name: 'tls_keylog_parse/nss-format',
      tool: 'tls_keylog_parse',
      origin: 'external-vector',
      reference:
        'Mozilla NSS SSLKEYLOGFILE format: CLIENT_RANDOM line with 32-byte client random and 48-byte secret must parse and summarize',
      run: () => handlers.handleTlsKeylogParse({ path: keylogPath }),
      validate: (v) => {
        const b = body(v);
        if (b.success === false) return `failed: ${b.error}`;
        const text = JSON.stringify(b).toLowerCase();
        if (!text.includes('client_random')) return 'CLIENT_RANDOM label not surfaced';
        if (!text.includes(CLIENT_RANDOM)) return 'planted client random not found';
        const summary = b.summary as Record<string, unknown> | undefined;
        if (summary && typeof summary === 'object') {
          const text2 = JSON.stringify(summary);
          if (!/1/.test(text2)) return `summary does not count 1 entry: ${text2.slice(0, 160)}`;
        }
        return true;
      },
    },
    {
      name: 'tls_parse_certificate/spki-wire-roundtrip',
      tool: 'tls_parse_certificate',
      origin: 'external-vector',
      reference:
        'X.509/SPKI DER wrapped in the RFC 8446 §4.4.2 Certificate message layout must roundtrip: count, length, SHA-256 fingerprint',
      run: () => handlers.handleParseCertificate({ rawHex: wrapCertMessage(certDer) }),
      validate: (v) => {
        const b = body(v);
        if (b.success === false) return `failed: ${b.error}`;
        const count = Number(b.certificateCount ?? -1);
        if (count !== 1) return `expected 1 certificate, got ${count}`;
        const text = JSON.stringify(b).toLowerCase();
        if (!text.includes(CERT_FINGERPRINT))
          return `SHA-256 fingerprint mismatch (expected ${CERT_FINGERPRINT.slice(0, 16)}…)`;
        if (!text.includes('cn=bench')) return 'subject CN not parsed';
        return true;
      },
    },
    {
      name: 'tls_parse_handshake/client-hello-rfc8446',
      tool: 'tls_parse_handshake',
      origin: 'external-vector',
      reference:
        'parses RFC 8446 ClientHello handshake record extracting serverName SNI and handshake metadata',
      run: () => handlers.handleParseHandshake({ rawHex: buildClientHelloHex() }),
      validate: (v) => {
        const b = body(v);
        if (b.success === false) return `failed: ${b.error}`;
        const handshake = b.handshake as Record<string, unknown> | undefined;
        if (!handshake || handshake.type !== 'client_hello')
          return `expected handshake.type === 'client_hello', got: ${JSON.stringify(b)}`;
        if (handshake.serverName !== 'benchmark.example.com')
          return `expected SNI benchmark.example.com, got: ${handshake.serverName}`;
        return true;
      },
    },
  ],
};
